import type { MapLayer } from '../elements/map-layer';
import type { MapmlViewer } from '../elements/mapml-viewer';

/**
 * Baked link data lifted from a `<map-a>` wrapper around a shape
 * inside a `<map-feature>`'s `<map-geometry>`. Rides along in the
 * emitted GeoJSON feature's `properties` so click / keyboard
 * activation paths can dispatch without a DOM crawl.
 */
export interface FeatureLinkProperties {
  /** Absolute or relative URL from the `<map-a href>` attribute. */
  linkHref: string;
  /** `_self` / `_blank` / `_parent` / `_top` — MapML.js parity. */
  linkTarget?: string;
  /** MIME type hint — e.g. `text/html`, `text/mapml`, `application/geo+json`. */
  linkType?: string;
  /** `<map-a inplace>` was present. */
  linkInplace?: boolean;
}

/**
 * Read the link properties baked into a GeoJSON feature's
 * `properties` object. Returns `null` when the properties don't
 * carry a `linkHref` (typical for a plain `<map-feature>` with no
 * `<map-a>` wrapper). Otherwise returns a normalised
 * {@link FeatureLinkProperties} object suitable for
 * {@link handleFeatureLink}.
 */
export function readFeatureLink(
  properties: Record<string, unknown> | null | undefined
): FeatureLinkProperties | null {
  if (!properties) return null;
  const href = properties.linkHref;
  if (typeof href !== 'string' || href === '') return null;
  const out: FeatureLinkProperties = { linkHref: href };
  const target = properties.linkTarget;
  if (typeof target === 'string' && target !== '') out.linkTarget = target;
  const type = properties.linkType;
  if (typeof type === 'string' && type !== '') out.linkType = type;
  if (properties.linkInplace === true) out.linkInplace = true;
  return out;
}

/**
 * The {@link FeatureLinkProperties} of a `<map-a>` element (MapML.js
 * path.js `_convertWrappers`), or `null` when it has no `href`.
 */
export function featureLinkFromElement(a: Element | null): FeatureLinkProperties | null {
  const href = a?.getAttribute('href');
  if (!a || !href) return null;
  const out: FeatureLinkProperties = { linkHref: href };
  const target = a.getAttribute('target');
  if (target) out.linkTarget = target;
  const type = a.getAttribute('type');
  if (type) out.linkType = type;
  if (a.hasAttribute('inplace')) out.linkInplace = true;
  return out;
}

/**
 * Port of MapML.js's `Util._handleLink` (see
 * `../MapML.js/src/mapml/utils/Util.js`). Follows a `<map-a>` feature
 * link according to its `href` + `target` + `type` + `inplace`:
 *
 *   - `type="text/html"`: any target but `_blank` behaves as `_top`
 *     (`window.location.href = url`); `_blank` opens a new window.
 *   - Otherwise an `href` containing `#` carries a `#zoom,lon,lat`
 *     location to go to; when nothing precedes the `#` the link only
 *     pans + zooms (unless `inplace`), and an `href` starting with `/`,
 *     `.` or `#` targets `_self`.
 *   - A new `<map-layer src=… checked>` is appended (`_blank`), replaces
 *     every layer (`_parent`) or replaces the owning layer (`_self` and
 *     anything else, keeping its opacity).
 *
 * Unless the link is `inplace`, once the new layer is ready (and, if it
 * has changed the map's projection, the change has finished or 5 s have
 * passed) the map zooms to the hash location, or else to the new layer;
 * then focus returns to the map.
 *
 * `owningLayer` is the `<map-layer>` holding the linked feature (MapML.js
 * passes its Leaflet layer).
 */
export function handleFeatureLink(
  viewer: MapmlViewer,
  owningLayer: MapLayer | null,
  link: FeatureLinkProperties
): void {
  const url = link.linkHref;
  // A `<map-a href>` is author-untrusted (a pasted/loaded
  // `<map-feature>` is inserted verbatim). Every branch below
  // navigates with `url` — `window.location.href`, `window.open`, or a
  // `<map-layer src>` — so a `javascript:` href would execute on
  // click. Reject anything that doesn't resolve to http(s) (relative
  // and `#hash` links resolve to the document's own scheme).
  let resolvedProtocol: string | null;
  try {
    resolvedProtocol = new URL(url, document.baseURI).protocol;
  } catch {
    resolvedProtocol = null;
  }
  if (resolvedProtocol !== 'http:' && resolvedProtocol !== 'https:') {
    console.warn(`MapML: ignoring map-a link with unsupported/unsafe URL: ${url}`);
    return;
  }
  const type = link.linkType;
  const inPlace = link.linkInplace === true;
  let target = link.linkTarget;
  let zoomTo: { z: number; lng: number; lat: number } | null = null;
  let justPan = false;
  let opacity: number | undefined;
  if (type === 'text/html' && target !== '_blank') {
    // all other target values other than _blank behave as _top
    target = '_top';
  } else if (type !== 'text/html' && url.includes('#')) {
    const hash = url.split('#');
    const loc = (hash[1] ?? '').split(',');
    zoomTo = { z: +(loc[0] || 0), lng: +(loc[1] || 0), lat: +(loc[2] || 0) };
    // nothing before the '#': the link is just for panning
    justPan = !hash[0];
    if (['/', '.', '#'].includes(url[0]!)) target = '_self';
  }
  const focusMap = (): void => {
    viewer.renderer.map?.getCanvas().focus();
  };
  if (!justPan) {
    const doc = viewer.ownerDocument ?? document;
    const layer = doc.createElement('map-layer') as MapLayer;
    layer.setAttribute('src', url);
    layer.setAttribute('checked', '');
    const postTraversalSetup = (): void => {
      // Set the viewer's lat / lon / zoom now, so a projection change the
      // traversal causes starts from the linked location.
      if (!inPlace && zoomTo) {
        viewer.lat = zoomTo.lat;
        viewer.lon = zoomTo.lng;
        viewer.zoom = zoomTo.z;
      }
      // The map's projection changes when the new layer is left alone on it
      // in another projection (MapML.js `selectAlternateOrChangeProjection`):
      // after a `_parent` link, or a `_self` link from the map's only layer.
      // Listen from now on, so the event can't be missed, and once the layer
      // is ready wait for it if the projection has changed, so that the zoom
      // below comes after the change has restored the view instead of being
      // undone by it.
      const projection = viewer.projection;
      let onProjectionChange = (): void => {};
      const projectionChanged = new Promise<void>((resolve) => {
        const timeout = setTimeout(resolve, 5000);
        onProjectionChange = () => {
          clearTimeout(timeout);
          resolve();
        };
        viewer.addEventListener('map-projectionchange', onProjectionChange, { once: true });
      });
      layer
        .whenReady()
        .then(() => {
          if (viewer.projection !== projection) return projectionChanged;
          viewer.removeEventListener('map-projectionchange', onProjectionChange);
          onProjectionChange();
          return undefined;
        })
        .then(() => {
          if (!inPlace && zoomTo) viewer.zoomTo(zoomTo.lat, zoomTo.lng, zoomTo.z);
          else if (!inPlace) layer.zoomTo();
          if (opacity) layer.opacity = opacity;
          focusMap();
        })
        .catch(() => {
          // the layer failed to load; it reports that itself
        });
    };
    switch (target) {
      case '_blank':
        if (type === 'text/html') {
          window.open(url);
        } else {
          postTraversalSetup();
          viewer.appendChild(layer);
        }
        break;
      case '_parent':
        postTraversalSetup();
        for (const other of Array.from(viewer.querySelectorAll(':scope > map-layer'))) {
          if (other !== owningLayer) other.remove();
        }
        viewer.appendChild(layer);
        owningLayer?.remove();
        break;
      case '_top':
        window.location.href = url;
        break;
      default:
        postTraversalSetup();
        if (owningLayer && owningLayer.isConnected) {
          opacity = owningLayer.opacity;
          owningLayer.insertAdjacentElement('beforebegin', layer);
          owningLayer.remove();
        } else {
          viewer.appendChild(layer);
        }
    }
  } else if (zoomTo && !inPlace) {
    viewer.zoomTo(zoomTo.lat, zoomTo.lng, zoomTo.z);
    focusMap();
  }
}
