/**
 * Draw a MapML tile matrix that isn't a power-of-two pyramid (CBMTILE,
 * and later custom projections) on MapLibre's quad tile grid.
 *
 * A CRS registered with `addProjection` is cut in a square quad tree
 * (`core/zoomScale.ts` {@link quadGrid}); where every MapML level halves
 * the last, MapML's tiles *are* MapLibre's, but CBMTILE's levels are
 * cartographic scales 1.6–1.8× apart. So the tile protocol handlers
 * compose each quad tile MapLibre asks for out of MapML tiles of one
 * level, in the same CRS: scale and translate only, no reprojection.
 *
 * Which level: MapML.js (Leaflet + Proj4Leaflet) draws level `z`'s own
 * tiles at zoom `z`, and the cartography (label size, generalisation)
 * belongs to its level, so the handlers pass the level on screen as a
 * hint. Two adjacent MapML levels can land on the same quad zoom, so the
 * quad tile alone can't tell which is on screen; the hint is taken
 * whenever the hinted level is one whose display requests this quad
 * zoom, and the level nearest the quad tile's resolution otherwise
 * (e.g. MapLibre filling in tiles mid-animation).
 *
 * The composite is drawn at the chosen level's own resolution, so at a
 * whole MapML level the GPU's scaling of the quad tile cancels out and
 * the native pixels reach the screen 1:1.
 */
import { tiledCrs } from '../core/projections';
import { quadGrid, toMapLibreZoom, toMapmlZoom, wholeMapmlZoom } from '../core/zoomScale';
import { decodeTileImage, fetchTileImage } from './mapLibreMapTileProtocol';

/** MapLibre's world square is 512 px wide at zoom 0. */
const MAPLIBRE_WORLD_SIZE = 512;

/** A quad tile's box in CRS (PCRS) units. */
export interface QuadTileBox {
  minx: number;
  miny: number;
  maxx: number;
  maxy: number;
  /** Side length of the square, in CRS units. */
  side: number;
}

/** One MapML tile in a {@link RegridPlan}, placed on the output canvas. */
export interface RegridSourceTile {
  col: number;
  row: number;
  /** Top-left of the tile on the output canvas, in output pixels. */
  dx: number;
  dy: number;
  /** Drawn width and height of the tile, in output pixels. */
  size: number;
}

/** How to compose one quad tile out of one MapML level's tiles. */
export interface RegridPlan {
  /** The MapML zoom level whose tiles are drawn. */
  zoom: number;
  /** Width and height of the output canvas, in pixels. */
  size: number;
  /** The MapML tiles covering the quad tile, clipped to the tile matrix. */
  tiles: RegridSourceTile[];
}

export interface RegridOptions {
  /** The raster source's `tileSize` (MapLibre's default 256). */
  tileSize?: number;
  /**
   * Whether the source rounds MapLibre's zoom to pick its tile zoom
   * (MapLibre's raster default) or floors it (`roundZoom = false`, the
   * GeoServer-aligned `<map-tile>` run and `text/mapml` sources).
   */
  roundZoom?: boolean;
  /** The whole MapML zoom level on screen. */
  level?: number;
}

/** The CRS box of MapLibre quad tile `q/x/y` (`y` counted down from the top). */
export function quadTileBox(projection: string, q: number, x: number, y: number): QuadTileBox {
  const grid = quadGrid(projection);
  const side = grid.extentAtZoom0 / 2 ** q;
  const minx = grid.origin[0] + x * side;
  const maxy = grid.origin[1] - y * side;
  return { minx, miny: maxy - side, maxx: minx + side, maxy, side };
}

/**
 * The quad zoom MapLibre requests a raster source's tiles at while it
 * shows MapML zoom `z`: its `coveringZoomLevel` (rounded for raster
 * sources unless `roundZoom` is off) at the MapLibre zoom
 * {@link toMapLibreZoom} draws `z` at.
 */
export function quadZoomForLevel(
  projection: string,
  z: number,
  tileSize = 256,
  roundZoom = true
): number {
  const m = toMapLibreZoom(projection, z) + Math.log2(MAPLIBRE_WORLD_SIZE / tileSize);
  // The tolerance keeps a computed 4.9999999 at 5 when flooring.
  return roundZoom ? Math.round(m) : Math.floor(m + 1e-9);
}

/**
 * The MapML level to draw quad tile zoom `q` with: `level` when it is
 * one whose display requests `q`, else the level whose resolution is
 * nearest (in scale) to the quad tile's, ties going to the finer level.
 */
export function regridLevel(projection: string, q: number, options: RegridOptions = {}): number {
  const { tileSize = 256, roundZoom = true, level } = options;
  const { resolutions } = tiledCrs(projection);
  if (
    level !== undefined &&
    Number.isInteger(level) &&
    level >= 0 &&
    level < resolutions.length &&
    quadZoomForLevel(projection, level, tileSize, roundZoom) === q
  ) {
    return level;
  }
  const quadRes = quadGrid(projection).extentAtZoom0 / 2 ** q / tileSize;
  let best = 0;
  let bestDistance = Infinity;
  resolutions.forEach((res, z) => {
    const distance = Math.abs(Math.log(res / quadRes));
    if (distance <= bestDistance + 1e-12) {
      best = z;
      bestDistance = Math.min(distance, bestDistance);
    }
  });
  return best;
}

/** The largest output canvas, as a multiple of `tileSize`. */
const MAX_SIZE_FACTOR = 2;

/**
 * Plan quad tile `q/x/y`: the MapML level to draw (see
 * {@link regridLevel}), the output size at that level's resolution, and
 * where each covering MapML tile lands on it. Null when the quad tile
 * lies outside the CRS's tile matrix.
 */
export function planRegrid(
  projection: string,
  q: number,
  x: number,
  y: number,
  options: RegridOptions = {}
): RegridPlan | null {
  const { tileSize = 256 } = options;
  const crs = tiledCrs(projection);
  const zoom = regridLevel(projection, q, options);
  const res = crs.resolutions[zoom]!;
  const box = quadTileBox(projection, q, x, y);
  const size = Math.min(
    MAX_SIZE_FACTOR * tileSize,
    Math.max(1, Math.round(box.side / res))
  );
  const pixel = box.side / size; // CRS units per output pixel
  const span = crs.tileSize * res; // one MapML tile's side, in CRS units
  const [ox, oy] = crs.origin;
  const cols = Math.ceil((crs.bounds.max[0] - ox) / span - 1e-9);
  const rows = Math.ceil((oy - crs.bounds.min[1]) / span - 1e-9);
  const c0 = Math.max(0, Math.floor((box.minx - ox) / span));
  const c1 = Math.min(cols - 1, Math.ceil((box.maxx - ox) / span - 1e-9) - 1);
  const r0 = Math.max(0, Math.floor((oy - box.maxy) / span));
  const r1 = Math.min(rows - 1, Math.ceil((oy - box.miny) / span - 1e-9) - 1);
  if (c0 > c1 || r0 > r1) return null;
  const tiles: RegridSourceTile[] = [];
  for (let row = r0; row <= r1; row++) {
    for (let col = c0; col <= c1; col++) {
      tiles.push({
        col,
        row,
        dx: (ox + col * span - box.minx) / pixel,
        dy: (box.maxy - (oy - row * span)) / pixel,
        size: span / pixel
      });
    }
  }
  return { zoom, size, tiles };
}

/** Loads MapML tile `zoom/col/row` as a drawable image, or null for none. */
export type RegridTileLoader = (
  zoom: number,
  col: number,
  row: number
) => Promise<CanvasImageSource | null>;

/**
 * Draw `plan`'s tiles onto one canvas. Resolves to the composite, which
 * a MapLibre protocol handler can return as its `data` as is, or null
 * when no tile loaded (the caller answers with a blank tile). A tile
 * whose load fails is left blank, as Leaflet leaves a failed tile.
 */
export async function composeRegrid(
  plan: RegridPlan,
  load: RegridTileLoader,
  signal?: AbortSignal
): Promise<ImageBitmap | null> {
  const canvas = new OffscreenCanvas(plan.size, plan.size);
  const ctx = canvas.getContext('2d');
  if (!ctx) return null;
  ctx.imageSmoothingQuality = 'high';
  let drawn = 0;
  await Promise.all(
    plan.tiles.map(async (t) => {
      const image = await load(plan.zoom, t.col, t.row).catch(() => null);
      if (!image || signal?.aborted) return;
      ctx.drawImage(image, t.dx, t.dy, t.size, t.size);
      drawn++;
    })
  );
  signal?.throwIfAborted();
  return drawn > 0 ? canvas.transferToImageBitmap() : null;
}

/** Decoded MapML tiles held for neighbouring quad tiles. */
const MAX_CACHED_TILES = 128;

const tileCache = new Map<string, Promise<ImageBitmap | null>>();

/** Fetches a MapML tile's image bytes, or null when there is no image. */
export type TileBytesFetcher = (url: string, init: RequestInit) => Promise<ArrayBuffer | null>;

/**
 * Fetch and decode a MapML tile image, once: a MapML tile usually
 * straddles several quad tiles, which MapLibre requests together, so
 * each image is requested from the server once (as MapML.js requests
 * it), whichever quad tiles it is drawn into. Not cancelled when one
 * quad tile's request is, since others may be waiting on it. Resolves
 * to null for a failed request or a body that isn't an image (e.g. a
 * WMS exception report); `fetchBytes` (the shared sniffing,
 * warn-once {@link fetchTileImage} by default) decides which those are,
 * and decoding goes through the shared bounded {@link decodeTileImage}.
 */
export function loadTileImage(
  url: string,
  init: RequestInit = {},
  fetchBytes: TileBytesFetcher = fetchTileImage
): Promise<ImageBitmap | null> {
  const cached = tileCache.get(url);
  if (cached) {
    // Most recently used last, so eviction drops the stalest.
    tileCache.delete(url);
    tileCache.set(url, cached);
    return cached;
  }
  const image: Promise<ImageBitmap | null> = fetchBytes(url, init)
    .then(async (bytes) => {
      if (bytes === null) return null;
      const decoded = await decodeTileImage(bytes);
      return decoded instanceof ArrayBuffer ? null : decoded;
    })
    .catch(() => null)
    .then((bitmap) => {
      // A failure is shared by the requests already waiting on it, but
      // the next one tries again.
      if (!bitmap && tileCache.get(url) === image) tileCache.delete(url);
      return bitmap;
    });
  tileCache.set(url, image);
  if (tileCache.size > MAX_CACHED_TILES) {
    tileCache.delete(tileCache.keys().next().value!);
  }
  return image;
}

/** Forget every cached MapML tile (tests; a layer whose tiles changed). */
export function clearRegridTileCache(): void {
  tileCache.clear();
}

/** The MapLibre map a re-gridded source is drawn on. */
export interface RegridMap {
  getZoom(): number;
}

/** One re-gridded source's state, held in its protocol registry entry. */
export interface RegridContext {
  projection: string;
  tileSize: number;
  roundZoom: boolean;
  /** The whole MapML level on screen, read as each tile is requested. */
  level(): number;
  /** Quad zoom → the MapML levels its tiles have been drawn from. */
  drawn: Map<number, Set<number>>;
}

/**
 * The re-grid state of a source drawn on `map` in `projection`, or null
 * where MapML's tiles are MapLibre's own (a power-of-two pyramid).
 */
export function createRegridContext(
  map: RegridMap,
  projection: string,
  options: { tileSize?: number; roundZoom?: boolean } = {}
): RegridContext | null {
  if (quadGrid(projection).native) return null;
  return {
    projection,
    tileSize: options.tileSize ?? 256,
    roundZoom: options.roundZoom ?? true,
    level: () => wholeMapmlZoom(toMapmlZoom(projection, map.getZoom())),
    drawn: new Map()
  };
}

/**
 * Compose quad tile `q/x/y` of a re-gridded source (see
 * {@link planRegrid}); null when it is outside the tile matrix or none
 * of its MapML tiles loaded.
 */
export async function regridQuadTile(
  ctx: RegridContext,
  q: number,
  x: number,
  y: number,
  load: RegridTileLoader,
  signal?: AbortSignal
): Promise<ImageBitmap | null> {
  const plan = planRegrid(ctx.projection, q, x, y, {
    tileSize: ctx.tileSize,
    roundZoom: ctx.roundZoom,
    level: ctx.level()
  });
  if (plan === null) return null;
  // Recorded at request time, so a tile still in flight when the view
  // settles counts too.
  let levels = ctx.drawn.get(q);
  if (!levels) ctx.drawn.set(q, (levels = new Set()));
  levels.add(plan.zoom);
  return composeRegrid(plan, load, signal);
}

/**
 * Whether the source's tiles at the quad zoom the level on screen is
 * drawn at came from another level — MapLibre filled them mid-zoom, or
 * the level changed without the quad zoom changing (two CBMTILE levels
 * can share one), so its cache holds the wrong level's tiles. If so the
 * record is reset, and the caller has the source re-request its tiles.
 * Call it when the view settles (`moveend`).
 */
export function regridIsStale(ctx: RegridContext): boolean {
  const level = ctx.level();
  const q = quadZoomForLevel(ctx.projection, level, ctx.tileSize, ctx.roundZoom);
  const expected = regridLevel(ctx.projection, q, {
    tileSize: ctx.tileSize,
    roundZoom: ctx.roundZoom,
    level
  });
  const levels = ctx.drawn.get(q);
  if (!levels || [...levels].every((z) => z === expected)) return false;
  ctx.drawn.clear();
  return true;
}
