import type * as maplibregl from 'maplibre-gl';

/**
 * Minimal subset of MapLibre GL's `Map` API the handle classes in
 * `MapLibreLayers.ts` speak to. Kept as a structural interface so
 * real `maplibregl.Map` satisfies it verbatim (a `Map` instance has
 * every one of these methods with matching signatures) and the fake
 * spy below can implement it without pulling in WebGL.
 */
export interface MapLibreMapLike {
  addSource(id: string, source: maplibregl.SourceSpecification): void;
  getSource(id: string): maplibregl.Source | undefined;
  removeSource(id: string): void;
  addLayer(
    spec: maplibregl.LayerSpecification,
    beforeId?: string
  ): void;
  getLayer(id: string): maplibregl.StyleLayer | undefined;
  removeLayer(id: string): void;
  moveLayer(id: string, beforeId?: string): void;
  setLayoutProperty(id: string, prop: string, value: unknown): void;
  getLayoutProperty(id: string, prop: string): unknown;
  setPaintProperty(id: string, prop: string, value: unknown): void;
  getPaintProperty(id: string, prop: string): unknown;
  /**
   * Feature-composite hover / click handlers are bound per-sub-layer.
   * The real MapLibre API accepts a rich event object; the handles
   * pass caller-supplied listener functions unchanged. The two-argument
   * form is a map-level event (`moveend`, for re-gridded tile sources).
   */
  on(type: string, listener: () => void): void;
  on(
    type: string,
    layer: string,
    listener: (e: maplibregl.MapLayerMouseEvent) => void
  ): void;
  off(type: string, listener: () => void): void;
  off(
    type: string,
    layer: string,
    listener: (e: maplibregl.MapLayerMouseEvent) => void
  ): void;
  /** MapLibre's zoom; re-gridded tile sources read the MapML level from it. */
  getZoom(): number;
  /**
   * Used by `MapLibreFeatureHandle.remove()`'s cleanup-if-empty
   * heuristic (retract the shared hover / content popups when the
   * last composite sub-layer goes away). The real Map returns a full
   * `StyleSpecification`; only `.layers[].id` is inspected.
   */
  getStyle(): { layers: Array<{ id: string; [k: string]: unknown }> };
  /**
   * Point the map's glyphs URL at a font server (typically the
   * demotiles endpoint, or a self-hosted mirror). Needed for
   * `symbol` layers with a `text-field` to render; a pmtiles
   * stylesheet declares its preferred URL via the top-level
   * `glyphs` field of the MapLibre style spec.
   */
  setGlyphs(glyphsUrl: string | null | undefined): void;
}

/**
 * Whether `map` shows a flat view, neither rotated, tilted nor a globe:
 * then its viewport is a PCRS box, as Leaflet's always is, and
 * `viewer.extent` is MapML.js's pixel bounds.
 */
export function isFlatView(
  map: Pick<maplibregl.Map, 'getPitch' | 'getBearing' | 'getProjection'>
): boolean {
  return (
    map.getPitch() === 0 &&
    map.getBearing() === 0 &&
    map.getProjection()?.type !== 'globe'
  );
}
