/**
 * The markup the layer context menu's Copy Layer / Copy Sub-layer put on
 * the clipboard: the element's outer HTML with its own `src` (a remote
 * `<map-layer>`) and every `<map-link>`'s `href` or `tref` made absolute,
 * so the copy still works when pasted into another page. Ports MapML.js's
 * `getOuterHTML` (`src/layer.js`, `src/map-extent.js`), including its
 * `decodeURI`, which keeps a `tref`'s `{var}` placeholders readable after
 * URL resolution.
 */
export function resolvedOuterHTML(el: Element, base: string): string {
  // Copied into a document with no browsing context, where custom
  // elements don't upgrade: a live clone would run the elements'
  // callbacks, and a detached `<map-extent>` would mark itself (and its
  // layer) `disabled` in the copy.
  const inert = document.implementation.createHTMLDocument('');
  const copy = inert.importNode(el, true);
  const src = copy.getAttribute('src');
  if (src !== null) copy.setAttribute('src', new URL(src, base).href);
  for (const link of copy.querySelectorAll('map-link')) {
    const attr = link.hasAttribute('href')
      ? 'href'
      : link.hasAttribute('tref')
        ? 'tref'
        : null;
    if (attr === null) continue;
    link.setAttribute(
      attr,
      decodeURI(new URL(link.getAttribute(attr)!, base).href)
    );
  }
  return copy.outerHTML;
}
