/**
 * `<area is="map-area">` — client-side image-map areas rendered as map
 * geometry.
 *
 * Ported from MapML.js `src/map-area.js`. An `<area>` child of
 * `<map is="web-map">` keeps its HTML image-map semantics (pixel
 * `coords` in the coordinate space of the `<img usemap>` poster, an
 * `href`, an `alt` accessible name) but is drawn as a shape on the map:
 * the pixel coordinates are unprojected against the map's *initial*
 * view, so the resulting geometry is geographic and pans / zooms with
 * the map.
 *
 * Differences from MapML.js, all forced by the renderer:
 *
 *  - Leaflet draws each area as its own SVG path with per-path options;
 *    MapLibre has no per-feature DOM, so the areas of one map are
 *    rendered as a single-feature GeoJSON source per `<area>` and styled
 *    via paint overrides derived from the element's computed style
 *    (same author-facing CSS surface: `fill`, `stroke`, `stroke-width`,
 *    `fill-opacity`, `stroke-opacity`).
 *  - `alt` becomes the feature's accessible name in the keyboard focus
 *    index rather than an `<svg:title>` tooltip.
 *  - Activation goes through the shared feature-link pipeline
 *    ({@link handleFeatureLink}) instead of a bare `window.open`, so
 *    `target` and `type` are honoured. The defaults (`_blank` +
 *    `text/html`) reproduce MapML.js's `window.open(this.href)`.
 */
import { shadowCrossingClosestViewer } from '../core/shadow';
import type { FeatureRendererLayer } from '../core/RendererHandles';
import type { PaintOverrides } from '../core/paintExpressions';
import type { MapmlViewer } from './mapml-viewer';

/** Points on the polygon approximating a `shape="circle"` area. */
const CIRCLE_SEGMENTS = 64;

/** Upper bound of the MapML zoom axis — areas render at every zoom. */
const MAX_ZOOM = 25;

let nextAreaLayerId = 0;

/** Viewer members `<area is="map-area">` needs, including web-map's poster. */
type AreaHost = MapmlViewer & { poster?: HTMLImageElement | null };

export class MapArea extends HTMLAreaElement {
  static readonly observedAttributes = [
    'coords',
    'alt',
    'href',
    'shape',
    'rel',
    'type',
    'target'
  ] as const;

  #viewer: AreaHost | null = null;
  #handle: FeatureRendererLayer | null = null;
  #connected = false;
  /** Re-raise the area above any layer that lands after it. */
  #raiseListener = (): void => this.#raise();

  connectedCallback(): void {
    const viewer = shadowCrossingClosestViewer(this) as AreaHost | null;
    // A plain `<area>` in an ordinary image map has no viewer — leave it
    // to the browser's own image-map machinery.
    if (viewer === null) return;
    this.#connected = true;
    this.#viewer = viewer;
    viewer.addEventListener('mapml:layerschanged', this.#raiseListener);
    void viewer.whenReady().then(() => {
      if (this.#connected) this.#render();
    });
  }

  disconnectedCallback(): void {
    this.#connected = false;
    this.#viewer?.removeEventListener('mapml:layerschanged', this.#raiseListener);
    this.#handle?.remove();
    this.#handle = null;
    this.#viewer = null;
  }

  attributeChangedCallback(): void {
    if (this.#connected) this.#render();
  }

  /**
   * (Re)build this area's geometry from its current `coords` / `shape`
   * and hand it to the renderer. Called once the map is ready and again
   * on any observed attribute change.
   */
  #render(): void {
    const viewer = this.#viewer;
    const map = viewer?.renderer.map;
    if (!viewer || !map) return;

    const ring = this.#ring(map, viewer.poster ?? null);
    if (ring === null) return;

    // `min` / `max` gate the renderer's per-feature zoom filter; areas
    // have no zoom range of their own, so they render at every zoom.
    const properties: Record<string, unknown> = {
      caption: this.alt,
      min: 0,
      max: MAX_ZOOM
    };
    const href = this.getAttribute('href') ?? '';
    if (href !== '') {
      properties.linkHref = href;
      // MapML.js opens area links with `window.open(this.href)`; the
      // shared link pipeline reproduces that for `_blank` + text/html,
      // while still honouring an author-supplied `target` / `type`.
      properties.linkTarget = this.getAttribute('target') ?? '_blank';
      properties.linkType = this.getAttribute('type') ?? 'text/html';
    }

    const data: GeoJSON.FeatureCollection = {
      type: 'FeatureCollection',
      features: [
        {
          type: 'Feature',
          id: 0,
          geometry: { type: 'Polygon', coordinates: [ring] },
          properties
        }
      ]
    };

    if (this.#handle === null) {
      this.#handle = viewer.renderer.createFeatureCollectionLayer({
        id: `map-area-${++nextAreaLayerId}`,
        data
      });
    } else {
      this.#handle.setData(data);
    }
    this.#handle.setStyle(this.#paintOverrides());
    this.#handle.setFocusItems([this.#focusItem(this.#handle.id, ring, properties)]);
    this.#raise();
  }

  /**
   * Areas hyperlink the map, so they belong on top of its content —
   * MapML.js gets that from Leaflet's overlay pane, but MapLibre paints
   * in layer order and a `<map-layer>`'s tiles are added after us.
   */
  #raise(): void {
    const map = this.#viewer?.renderer.map;
    const id = this.#handle?.id;
    if (!map || id === undefined) return;
    for (const sub of [`${id}:fill`, `${id}:line`, `${id}:circle`]) {
      if (map.getLayer(sub)) map.moveLayer(sub);
    }
  }

  /**
   * The area's outline as a closed GeoJSON linear ring in lng/lat.
   * Returns `null` when `coords` are unusable for the declared shape.
   */
  #ring(
    map: NonNullable<MapmlViewer['renderer']['map']>,
    poster: HTMLImageElement | null
  ): [number, number][] | null {
    const unproject = (p: [number, number]): [number, number] => {
      const ll = map.unproject(p);
      return [ll.lng, ll.lat];
    };
    const close = (pts: [number, number][]): [number, number][] | null => {
      const first = pts[0];
      if (first === undefined) return null;
      return [...pts.map(unproject), unproject(first)];
    };

    const shape = (this.getAttribute('shape') ?? 'default').toLowerCase();
    if (shape === 'default') {
      // The whole visible map is the hyperlink target — MapML.js uses
      // `map.getBounds()` for the same case.
      const b = map.getBounds();
      const w = b.getWest();
      const s = b.getSouth();
      const e = b.getEast();
      const n = b.getNorth();
      return [
        [w, n],
        [e, n],
        [e, s],
        [w, s],
        [w, n]
      ];
    }

    const points = this.#coordsToArray(poster);
    if (points.length === 0) return null;

    if (shape === 'circle') {
      const radius = Number(this.coords.split(',')[2]);
      const center = points[0];
      if (center === undefined || !Number.isFinite(radius) || radius <= 0) return null;
      const [cx, cy] = center;
      const circle: [number, number][] = [];
      for (let i = 0; i < CIRCLE_SEGMENTS; i++) {
        const angle = (i / CIRCLE_SEGMENTS) * 2 * Math.PI;
        circle.push([cx + radius * Math.cos(angle), cy + radius * Math.sin(angle)]);
      }
      return close(circle);
    }
    if (shape === 'poly') {
      if (points.length < 3) return null;
      return close(points);
    }
    // `rect`: two opposite corners.
    const topLeft = points[0];
    const bottomRight = points[1];
    if (topLeft === undefined || bottomRight === undefined) return null;
    const [x1, y1] = topLeft;
    const [x2, y2] = bottomRight;
    return close([
      [x1, y1],
      [x2, y1],
      [x2, y2],
      [x1, y2]
    ]);
  }

  /**
   * `coords` as `[x, y]` pixel pairs, recentred when the map carries a
   * poster image: the `<img usemap>` may be laid out at a different size
   * than the map element, and MapML.js shifts the coordinates by half
   * the difference on each axis so the shapes line up with what the
   * author saw in the image map.
   */
  #coordsToArray(poster: HTMLImageElement | null): [number, number][] {
    const values = this.coords
      .split(',')
      .map((n) => parseInt(n, 10))
      .filter((n) => Number.isFinite(n));
    const points: [number, number][] = [];
    for (let i = 1; i < values.length; i += 2) {
      const x = values[i - 1];
      const y = values[i];
      if (x === undefined || y === undefined) continue;
      points.push([x, y]);
    }
    if (poster === null || points.length === 0) return points;
    const viewer = this.#viewer;
    if (!viewer) return points;
    const dx = ((poster.naturalWidth || poster.width) - viewer.width) / 2;
    const dy = ((poster.naturalHeight || poster.height) - viewer.height) / 2;
    return points.map(([x, y]) => [x - dx, y - dy]);
  }

  /**
   * Paint overrides derived from the element's computed style. MapML.js
   * reads the same SVG properties in `_styleToPathOptions`; `stroke:
   * none` / `fill: none` become a zero opacity here since MapLibre's
   * fill and line sub-layers are always present.
   */
  #paintOverrides(): PaintOverrides {
    const style = window.getComputedStyle(this);
    const stroked = style.stroke !== 'none' && style.stroke !== '';
    const filled = style.fill !== 'none' && style.fill !== '';
    const num = (value: string, fallback: number): number => {
      const n = parseFloat(value);
      return Number.isFinite(n) ? n : fallback;
    };
    return {
      fill: {
        'fill-color': filled ? style.fill : '#000000',
        'fill-opacity': filled ? num(style.fillOpacity, 1) : 0
      },
      line: {
        'line-color': stroked ? style.stroke : '#000000',
        'line-opacity': stroked ? num(style.strokeOpacity, 1) : 0,
        'line-width': num(style.strokeWidth, 1)
      },
      circle: {}
    };
  }

  /** Keyboard-focus proxy so an area is reachable by Tab, like a feature. */
  #focusItem(
    sourceId: string,
    ring: readonly [number, number][],
    properties: Record<string, unknown>
  ) {
    let west = Infinity;
    let south = Infinity;
    let east = -Infinity;
    let north = -Infinity;
    for (const [lng, lat] of ring) {
      west = Math.min(west, lng);
      east = Math.max(east, lng);
      south = Math.min(south, lat);
      north = Math.max(north, lat);
    }
    return {
      sourceId,
      featureId: 0,
      featureEl: this as HTMLElement,
      caption: this.alt,
      hasPopup: false,
      hasLink: this.getAttribute('href') !== null,
      centerLng: (west + east) / 2,
      centerLat: (south + north) / 2,
      bboxWest: west,
      bboxSouth: south,
      bboxEast: east,
      bboxNorth: north,
      zoom: 0,
      min: 0,
      max: MAX_ZOOM,
      // Keyboard activation reads the link straight off this bag.
      properties
    };
  }
}
