/**
 * `<map is="web-map">` — the customized-built-in viewer element.
 *
 * Ported from MapML.js `src/web-map.js`, which ships as a full duplicate
 * of `src/mapml-viewer.js`. Here the implementation is shared via
 * {@link MapmlViewerMixin}; this module overrides only the seams that
 * genuinely differ from the autonomous `<mapml-viewer>`:
 *
 *  - an `HTMLMapElement` cannot host a shadow root, so the map chrome
 *    lives on a child `<div class="mapml-web-map">` whose shadow root is
 *    exposed through the shared `renderRoot` accessor;
 *  - the "default object size" (300×150), border and `all: initial`
 *    reset are applied to the `<map>` element itself by a document-level
 *    stylesheet keyed to `[is="web-map"]`, rather than by a `:host` rule;
 *  - light-DOM children other than `<area>` and the shadow-host div are
 *    hidden, since MapML markup is not meant to render as HTML;
 *  - `areas` exposes the `<area is="map-area">` children.
 *
 * Unlike MapML.js, the host div is **not** `display: contents`: the
 * shared shadow stylesheet positions `.container` absolutely, which
 * needs the host to generate a box (and hence a containing block). It's
 * a plain block that fills the `<map>`.
 *
 * Customized built-ins are unsupported in WebKit/Safari — the same
 * platform caveat MapML.js carries.
 */
import { MapmlViewerMixin } from './mapml-viewer';

const WEB_MAP_DEFAULT_STYLE_ID = 'web-map-default-style';
const HOST_DIV_CLASS = 'mapml-web-map';

/**
 * Default object size + light-DOM resets for `<map is="web-map">`,
 * ported from MapML.js `web-map.js#_initShadowRoot`.
 *
 * `all: initial` stops inheritable page styles leaking into the map's
 * components (MapML.js issue #140); `contain: layout size` decouples the
 * element's size from its contents, which is also why the 300×150
 * default is mandatory rather than cosmetic.
 */
const WEB_MAP_DEFAULT_CSS = `
[is="web-map"] {
  all: initial;
  contain: layout size;
  display: inline-block;
  position: relative;
  width: 300px;
  height: 150px;
  border-width: 2px;
  border-style: inset;
  box-sizing: inherit;
}
[is="web-map"][frameborder="0"] { border-width: 0; }
[is="web-map"][hidden] { display: none !important; }
[is="web-map"] > .${HOST_DIV_CLASS} { display: block; width: 100%; height: 100%; }
[is="web-map"] > :not(area):not(.${HOST_DIV_CLASS}) { display: none !important; }
`;

export class WebMap extends MapmlViewerMixin(HTMLMapElement) {
  #poster: HTMLImageElement | null = null;

  /** The `<area>` children of this map, per `HTMLMapElement.areas`. */
  override get areas(): HTMLCollectionOf<HTMLAreaElement> {
    return this.getElementsByTagName('area');
  }

  /**
   * The `<img usemap="#name">` this map is the image map for, when the
   * author wrote one. `<area is="map-area">` children use it to rescale
   * their pixel `coords` (the image may be laid out at a different size
   * than the map). Ported from MapML.js `web-map.js#connectedCallback`.
   */
  get poster(): HTMLImageElement | null {
    return this.#poster;
  }

  override connectedCallback(): void {
    super.connectedCallback();
    this.#resolvePoster();
  }

  /**
   * Find and hide the poster image. MapML.js hides it because the map
   * renders the same content — leaving it visible would double it up.
   */
  #resolvePoster(): void {
    const name = this.getAttribute('name');
    if (name === null || name === '') return;
    this.#poster = document.querySelector<HTMLImageElement>(
      `img[usemap="#${CSS.escape(name)}"]`
    );
    this.#poster?.setAttribute('hidden', '');
  }

  override _attachShadowRoot(): ShadowRoot {
    let rootDiv = this.querySelector<HTMLDivElement>(`:scope > div.${HOST_DIV_CLASS}`);
    if (rootDiv === null) {
      rootDiv = document.createElement('div');
      rootDiv.className = HOST_DIV_CLASS;
      this.appendChild(rootDiv);
    }
    this.#installDefaultStyle();
    return rootDiv.shadowRoot ?? rootDiv.attachShadow({ mode: 'open' });
  }

  override disconnectedCallback(): void {
    super.disconnectedCallback();
    const rootDiv = this.querySelector(`:scope > div.${HOST_DIV_CLASS}`);
    rootDiv?.remove();
    this._teardownRenderRoot();
    this.#poster = null;
  }

  /**
   * Install the shared `[is="web-map"]` stylesheet once per root. A
   * viewer inside another element's shadow root needs its own copy —
   * document stylesheets don't cross the boundary.
   */
  #installDefaultStyle(): void {
    const root = this.getRootNode();
    const inShadow = root instanceof ShadowRoot;
    const existing = inShadow
      ? root.getElementById(WEB_MAP_DEFAULT_STYLE_ID)
      : document.getElementById(WEB_MAP_DEFAULT_STYLE_ID);
    if (existing !== null) return;
    const style = document.createElement('style');
    style.id = WEB_MAP_DEFAULT_STYLE_ID;
    style.textContent = WEB_MAP_DEFAULT_CSS;
    (inShadow ? root : document.head).prepend(style);
  }
}
